results = vector_store.search(
    query=user_question,
    filter={
        'classification': {'$in': user_allowed_tiers},  # e.g., ['public', 'internal', 'confidential']
        '$or': [
            {'contains_pii': False},
            {'student_ref': {'$in': user_authorized_students}}  # for scoped access
        ]
    },
    top_k=10
